  (* [comment removed for export] *)
  #[using="sp0 Hsp fdata LEN CFG PL"] Lemma stdout_agree : forall j (MV MV' : word -> option byte), stdoutA j MV -> stdoutXA MV -> 0 <= j <= 500 ->
    (forall a, 1422992 <= a < 1422992 + 232 \/ SOBUF <= a < SOBUF + 1024 -> MV' (Z_to_bv 64 a) = MV (Z_to_bv 64 a)) ->
    stdoutA j MV' /\ stdoutXA MV'.
  Proof.
    intros j MV MV' (F1 & F2 & F3 & F4 & F5 & F6 & F7 & FW & BW & BC) (X1 & X2 & X3 & X4 & X5) Hj AG.
    assert (TR : forall a (n : nat) bs, rdn ASEGS MV (Z_to_bv 64 a) n = Some bs -> 1422992 <= a -> a + Z.of_nat n <= 1422992 + 232 -> rdn ASEGS MV' (Z_to_bv 64 a) n = Some bs).
    { intros a n bs Hr H1 H2. apply (rdn_tr MV MV' a n bs Hr); [lia | lia|]. intros i Hi. apply AG. left. lia. }
    assert (TRB : forall a (n : nat) bs, rdn ASEGS MV (Z_to_bv 64 a) n = Some bs -> SOBUF <= a -> a + Z.of_nat n <= SOBUF + 1024 -> rdn ASEGS MV' (Z_to_bv 64 a) n = Some bs).
    { intros a n bs Hr H1 H2. apply (rdn_tr MV MV' a n bs Hr); [unfold SOBUF in *; lia | unfold SOBUF in *; lia|]. intros i Hi. apply AG. right. lia. }
    split.
    - unfold stdoutA. repeat split; try (apply TR; [assumption | cbn; lia | cbn; lia]).
      + intros a n H1 H2 d k Hd Hk. apply (store_ok_window ASEGS MV' (Z_to_bv 64 1422992) (Z_to_bv 64 (a + d)) 232%nat k 1422992 (1422992 + 232));
          first [exact wseg_sofile | reflexivity | lia | (rewrite u_small by lia; lia)].
      + intros a n H1 H2 d k Hd Hk. apply (store_ok_window ASEGS MV' (Z_to_bv 64 SOBUF) (Z_to_bv 64 (a + d)) 1024%nat k SOBUF (SOBUF + 1024));
          first [exact wseg_sobuf | reflexivity | (unfold SOBUF in *; lia) | (rewrite u_small by (unfold SOBUF in *; lia); unfold SOBUF in *; lia)].
      + destruct (BC i H) as (B1 & _). apply TRB; [exact B1 | lia | cbn; lia].
      + destruct (BC i H) as (_ & B2). apply TRB; [exact B2 | lia | cbn; lia].
    - unfold stdoutXA. repeat split; apply TR; first [assumption | cbn; lia].
  Qed.

  (* [comment removed for export] *)
  #[using="sp0 Hsp fdata LEN CFG PL"] Lemma stdout0_of_kn : forall E (MV : word -> option byte) kn, know_ok ASEGS E MV kn -> existsb (kentry_eqb (KImg 0x15b690 0x15b778)) kn = true -> stdout0A MV.
  Proof.
    intros E MV kn HK Hb. pose proof (kimg_clear E MV kn 0x15b690 0x15b778 HK Hb) as CL.
    assert (IC : forall a (n : nat) bs, rdn ASEGS (fun _ => None) (Z_to_bv 64 a) n = Some bs -> (0x15b690 <=? a) && (a + Z.of_nat n <=? 0x15b778) = true -> rdn ASEGS MV (Z_to_bv 64 a) n = Some bs).
    { intros a n bs Hr Hc. apply andb_prop in Hc as (B1 & B2). apply Z.leb_le in B1, B2. apply (img_cell MV a n bs Hr); [lia | lia|]. intros i Hi. apply CL. lia. }
    unfold stdout0A.
    split; [exact (IC 1423132 4%nat (word_to_le_bytes 4 (Z_to_bv 64 4294967295)) ltac:(img_rd) eq_refl)|]. split; [exact (IC 1422992 4%nat (word_to_le_bytes 4 (Z_to_bv 64 5)) ltac:(img_rd) eq_refl)|].
    split; [exact (IC 1423088 8%nat (word_to_le_bytes 8 (Z_to_bv 64 1024)) ltac:(img_rd) eq_refl)|]. split; [exact (IC 1423024 8%nat (word_to_le_bytes 8 (Z_to_bv 64 0)) ltac:(img_rd) eq_refl)|].
    split; [exact (IC 1423128 4%nat (word_to_le_bytes 4 (Z_to_bv 64 0)) ltac:(img_rd) eq_refl)|]. split; [exact (IC 1423080 8%nat (word_to_le_bytes 8 (Z_to_bv 64 SOBUF)) ltac:(img_rd) eq_refl)|].
    split; [exact (IC 1423136 4%nat (word_to_le_bytes 4 (Z_to_bv 64 10)) ltac:(img_rd) eq_refl)|]. split; [exact (IC 1423064 8%nat (word_to_le_bytes 8 (Z_to_bv 64 1311504)) ltac:(img_rd) eq_refl)|].
    split; [exact (IC 1423112 4%nat (word_to_le_bytes 4 (Z_to_bv 64 1)) ltac:(img_rd) eq_refl)|].
    split.
    - intros a n H1 H2 d k Hd Hk. apply (store_ok_window ASEGS MV (Z_to_bv 64 1422992) (Z_to_bv 64 (a + d)) 232%nat k 1422992 (1422992 + 232));
        first [exact wseg_sofile | reflexivity | lia | (rewrite u_small by lia; lia)].
    - intros a n H1 H2 d k Hd Hk. apply (store_ok_window ASEGS MV (Z_to_bv 64 SOBUF) (Z_to_bv 64 (a + d)) 1024%nat k SOBUF (SOBUF + 1024));
        first [exact wseg_sobuf | reflexivity | (unfold SOBUF in *; lia) | (rewrite u_small by (unfold SOBUF in *; lia); unfold SOBUF in *; lia)].
  Qed.

