Definition stderrM6 (MV : word -> option byte) : Prop :=
  stderrMA MV /\ rdn ASEGS MV (Z_to_bv 64 1422984) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 1422752)) /\ rdn ASEGS MV (Z_to_bv 64 1422892) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 4294967295)).
Lemma stderrM6_tr : forall (MV MV' : word -> option byte), stderrM6 MV -> (forall a, 1422752 <= a < 1422992 -> MV' (Z_to_bv 64 a) = MV (Z_to_bv 64 a)) -> stderrM6 MV'.
Proof.
  intros MV MV' ((S1 & S2 & S3 & S4) & S5 & S6) AG.
  assert (TR : forall a (n : nat) bs, rdn ASEGS MV (Z_to_bv 64 a) n = Some bs -> 1422752 <= a -> a + Z.of_nat n <= 1422992 -> rdn ASEGS MV' (Z_to_bv 64 a) n = Some bs).
  { intros a n bs Hr H1 H2. apply (rdn_tr MV MV' a n bs Hr); [lia | lia|]. intros i Hi. apply AG. lia. }
  unfold stderrM6, stderrMA. repeat split; apply TR; first [assumption | cbn; lia].
Qed.
