Lemma msg_itinerary_okA :
  (s_pc (fst (fst rMS)), s_log (fst (fst rMS)), s_pc (fst (fst rMS2)), snd (fst rMS2), s_log (fst (fst rMS2)), s_pc (fst (fst rMS4)), snd (fst rMS4), s_log (fst (fst rMS4)))
  = (0x6a2bc, [], 0x8073c, [], [], 0x137cc8, [], [])
  /\ (nth 1 srMS (ELit 0), nth 2 srMS (ELit 0), nth 10 srMS (ELit 0), nth 11 srMS (ELit 0), nth 12 srMS (ELit 0), nth 13 srMS (ELit 0))
     = (ELit 715808, EAlu ALU_ADD (EVar 0) (ELit (-128)), ELit 139118, ELit 31, ELit 1, ELit 1422752)
  /\ (nth 1 srMS2 (ELit 0), nth 2 srMS2 (ELit 0), nth 4 srMS2 (ELit 0), nth 10 srMS2 (ELit 0)) = (ELit 0xaec28, EAlu ALU_ADD (EVar 0) (ELit (-128)), ELit 6896384, EVar 48)
  /\ (nth 2 srMS4 (ELit 0), nth 4 srMS4 (ELit 0), nth 10 srMS4 (ELit 0)) = (EAlu ALU_ADD (EVar 0) (ELit (-48)), ELit 6896384, ELit 2)
  /\ forallb (fun K => existsb (kentry_eqb K) knMS4) XKNM = true /\ has_window knMS4 = true
  /\   (s_pc (fst (fst rMO)), s_log (fst (fst rMO)), s_pc (fst (fst rMO2)), snd (fst rMO2), s_log (fst (fst rMO2)), s_pc (fst (fst rMO4)), snd (fst rMO4), s_log (fst (fst rMO4)))
  = (0x6a2bc, [], 0x8073c, [], [], 0x137cc8, [], [])
  /\ (nth 1 srMO (ELit 0), nth 2 srMO (ELit 0), nth 10 srMO (ELit 0), nth 11 srMO (ELit 0), nth 12 srMO (ELit 0), nth 13 srMO (ELit 0))
     = (ELit 715808, EAlu ALU_ADD (EVar 0) (ELit (-128)), ELit 91362, ELit 31, ELit 1, ELit 1422752)
  /\ (nth 1 srMO2 (ELit 0), nth 2 srMO2 (ELit 0), nth 4 srMO2 (ELit 0), nth 10 srMO2 (ELit 0)) = (ELit 0xaec28, EAlu ALU_ADD (EVar 0) (ELit (-128)), ELit 6896384, EVar 48)
  /\ (nth 2 srMO4 (ELit 0), nth 4 srMO4 (ELit 0), nth 10 srMO4 (ELit 0)) = (EAlu ALU_ADD (EVar 0) (ELit (-48)), ELit 6896384, ELit 2)
  /\ forallb (fun K => existsb (kentry_eqb K) knMO4) XKNM = true /\ has_window knMO4 = true.
Proof.
vm_compute. repeat split; reflexivity. Qed.

