    assert (HS16 : S mod 16 = 0) by (unfold S; clear - Hal; lia).
    Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
    assert (HW : has_window knMO = true) by (vm_compute; reflexivity).
    assert (G1r : getr R 1%bv = Z_to_bv 64 715808) by (regv HR (1%bv : reg); reflexivity).
    assert (G2r : getr R 2%bv = Z_to_bv 64 S) by (regv HR (2%bv : reg); cbn [edenot ev ENVA]; rewrite P0; apply alu_add_w_litA).
    assert (G10r : getr R 10%bv = Z_to_bv 64 91362) by (regv HR (10%bv : reg); reflexivity).
    assert (G11r : getr R 11%bv = Z_to_bv 64 31) by (regv HR (11%bv : reg); reflexivity).
    assert (G12r : getr R 12%bv = Z_to_bv 64 1) by (regv HR (12%bv : reg); reflexivity).
    assert (G13r : getr R 13%bv = Z_to_bv 64 1422752) by (regv HR (13%bv : reg); reflexivity).
    assert (CANc : rdn ASEGS MV (Z_to_bv 64 7027520) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (bv_unsigned can)))).
    { rewrite Z_to_bv_bv_unsigned, <- P3. exact (kword_lit sp0 _ MV _ 7027520 8%nat (EVar 3) HK ltac:(vm_compute; reflexivity) ltac:(lia) ltac:(cbn; lia)). }
    pose proof (kimg_clear _ MV _ 1422752 1422992 HK ltac:(vm_compute; reflexivity)) as SEIMG.
    assert (WIN : forall a n, usp - 6144513 <= a -> a + n <= usp -> forall d (k : nat), 0 <= d -> d + Z.of_nat k <= n -> store_ok ASEGS MV (Z_to_bv 64 (a + d)) k = true)
      by (intros a n Ha Hn d k Hd Hk; exact (stk_wr sp0 Hsp vals _ MV _ a n HK HW P0 Ha Hn d k Hd Hk)).
