  assert (Dpd : 0 <= (pd + n - 1) / 8 <= 2 ^ 44) by (unfold HIGHBEG, HIGHEND in *; split; [apply Z.div_pos; lia | apply Z.div_le_upper_bound; lia]).
  destruct (@diag_memcpy fx M s pd ps n bs (Z_to_bv 64 1311008) R) as (R' & Mj & RUN & V10 & KCS & OUT & GR).
