  - apply (store_ok_of_writable M pd n); [exact W2 | rewrite En; rewrite Nat2Z.id; reflexivity].
  - rewrite En, Nat2Z.id. exact RD.
  - exact RET.
  - exact HG.
  - exact HI.
  - exact ZS.
