  #[using="Type"] Lemma kword_sp : forall vals ebs (MV : word -> option byte) kn off (w : nat) v,
    know_ok ASEGS (Env (vals_ev vals) ebs) MV kn -> existsb (kentry_eqb (KWord (SA (EVar 0) off) w v)) kn = true -> vals_ev vals 0 = sp0 ->
